package org.apache.commons.lang3;

import junit.framework.TestCase;

public class StringEscapeUtilsBugOriginTest extends TestCase {
    public void testEscapeJavaScriptSlash() {
        String input = "<" + "script>alert('aaa');<" + "/script>";
        String expected = "<" + "script>alert('aaa');<" + "\\" + "/script>";
        String result = StringEscapeUtils.escapeJavaScript(input);
        assertEquals("StringEscapeUtils.escapeJavaScript should escape '/' to '<redacted URL>'", expected, result);
    }
}
